declarations.ContextForm:
function ContextForm({ locale, reload, event }) {
  const c = COPY[locale],
    [show, setShow] = useState(Boolean(event)),
    [label, setLabel] = useState(event?.label || ''),
    [note, setNote] = useState(event?.note || ''),
    [date, setDate] = useState(
      event
        ? new Date(
            new Date(event.occurredAt).getTime() -
              new Date(event.occurredAt).getTimezoneOffset() * 60000,
          )
            .toISOString()
            .slice(0, 16)
        : '',
    ),
    [busy, setBusy] = useState(false),
    [error, setError] = useState(null)
  async function submit(e) {
    e.preventDefault()
    setBusy(true)
    try {
      await appFetch(event ? 'context/' + event.id : 'context', {
        action: 'save',
        label,
        note,
        occurredAt: new Date(date).toISOString(),
        timezone: localZone(),
        ...(event ? { expectedRevision: event.revision } : {}),
      })
      if (!event) {
        setLabel('')
        setNote('')
        setShow(false)
      }
      await reload()
    } catch (e) {
      setError(e)
    } finally {
      setBusy(false)
    }
  }
  return (
    <section className="hh-context">
      {!show ? (
        <button onClick={() => setShow(true)}>＋ {c.addEvent}</button>
      ) : (
        <form onSubmit={submit} className="hh-form hh-panel">
          <h2>{c.context}</h2>
          <p>{c.contextNote}</p>
          <label>
            {c.label}
            <input
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              required
              maxLength={200}
            />
          </label>
          <label>
            {c.date}
            <input
              type="datetime-local"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              required
            />
          </label>
          <label>
            {c.note}
            <textarea value={note} onChange={(e) => setNote(e.target.value)} maxLength={1000} />
          </label>
          <button className="hh-primary" disabled={busy}>
            {c.save}
          </button>
          {!event && (
            <button type="button" onClick={() => setShow(false)}>
              {c.cancel}
            </button>
          )}
          {error && <p role="alert">{message(error, c)}</p>}
        </form>
      )}
    </section>
  )
}

declarations.monitoringFetch:
async function monitoringFetch(path, body) {
  const response = await fetch('/api/app/' + path, {
    method: body ? 'POST' : 'GET',
    cache: 'no-store',
    credentials: 'same-origin',
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  })
  const value = await response.json().catch(() => ({ error: 'SERVICE_UNAVAILABLE' }))
  if (!response.ok) {
    const error = new Error(value.error || 'SERVICE_UNAVAILABLE')
    error.code = value.error
    throw error
  }
  return value
}

declarations.statusReason:
function statusReason(c, state) {
  return (
    {
      in_progress: c.resumeReason,
      not_completed: c.incompleteReason,
      completed: c.completedReason,
      up_to_date: c.currentReason,
      due_soon: c.dueSoonReason,
      due_now: c.dueReason,
    }[state] || ''
  )
}

